// Picks a Material Icon Theme icon (see icon-map.js, generated by scripts/gen-icons.mjs).
import { EXT, NAMES, FOLDERS, HAS_OPEN } from "./icon-map.js";

export function iconFor(name, isDir, open) {
  const lower = String(name).toLowerCase();
  if (isDir) {
    const n = FOLDERS[lower] ?? FOLDERS[lower.replace(/^\./, "")];
    if (!n) return open ? "folder-open" : "folder";
    return open && HAS_OPEN[n] ? `${n}-open` : n;
  }
  if (NAMES[lower]) return NAMES[lower];
  const parts = lower.split(".");
  // Longest dotted suffix first: "a.test.ts" tries "test.ts", then "ts".
  for (let i = 1; i < parts.length; i++) {
    const hit = EXT[parts.slice(i).join(".")];
    if (hit) return hit;
  }
  return "file";
}

export const iconPath = (icon) => `mods/files-tabs/icons/${icon}.svg`;
